'use strict';
// Functional workspaces: selection and work happen on the same page.
Object.assign(names,{logcenter:'日志中心',collectioncenter:'日志回捞',issues:'问题工单',workbench:'问题排查',parsing:'解析状态',logs:'日志阅读',collect:'回捞进度',source:'源码关联',report:'问题排查'});
let fullLogSources=logSources;
function collectionSources(){return fullLogSources().filter(x=>!x.asset);}
const workUI=Object.assign({logKey:null,collectionKey:null,logMode:'parse',collectionMode:'push',issueMode:'chat',issueDetail:false,logQuery:'',collectionQuery:'',issueQuery:''},state.workspaceUI||{});
const demoRuns=new Map();let originalGo=go;
function persistWork(){state.workspaceUI={...workUI,issueDetail};save();}
function receivedLogSources(){return fullLogSources().filter(x=>x.request.files.some(f=>['已上传','可查','解析失败'].includes(f.status)));}
function primarySection(route){return ['logcenter','parsing','logs'].includes(route)?'logcenter':['collectioncenter','collect'].includes(route)?'collectioncenter':route==='source'&&state.navigationOrigin==='logcenter'?'logcenter':'issues';}
function selectedLog(){let all=receivedLogSources();return all.find(x=>x.key===workUI.logKey)||all[0];}
function selectedCollection(){let all=collectionSources();if(workUI.collectionMode==='retry')all=all.filter(x=>['部分成功','解析失败','上传失败','设备响应超时','推送失败','无可用日志','设备不支持'].includes(x.request.status));return all.find(x=>x.key===workUI.collectionKey)||all[0];}
function syncLog(x){if(!x)return;state.active=x.issue.id;taskId=x.request.task;requestId=x.request.id;workUI.logKey=x.key;if(x.request.task&&!availableIndices().includes(selected))selected=availableIndices()[0];}
function syncCollection(x){if(!x)return;state.active=x.issue.id;requestId=x.request.id;workUI.collectionKey=x.key;}
function setLogSelection(key){let x=receivedLogSources().find(x=>x.key===key);syncLog(x);selected=4;query='';level='全部';contextMode=false;persistWork();render();}
function setCollectionSelection(key){syncCollection(fullLogSources().find(x=>x.key===key));persistWork();render();}
function setIssueSelection(id){state.active=id;taskId=null;requestId=null;selected=4;draftHandoff=null;persistWork();render();}
function setLogMode(mode){workUI.logMode=mode;persistWork();go('logcenter');}
function setCollectionMode(mode){workUI.collectionMode=mode;persistWork();go('collectioncenter');}
function setIssueMode(mode){workUI.issueMode=mode;inspectorTab=mode==='hypotheses'?'hypotheses':'evidence';if(mode==='handoff')draftHandoff=null;persistWork();go('workbench');}
go=function(route){if(route==='parsing'){workUI.logMode='parse';route='logcenter';}else if(route==='logs'){let found=fullLogSources().find(x=>x.request.task===taskId);if(found){workUI.logKey=found.key;workUI.logStatus='';workUI.logQuery='';}workUI.logMode='read';route='logcenter';}else if(route==='collect'){workUI.collectionMode='push';workUI.collectionStatus='';workUI.collectionQuery='';let found=fullLogSources().find(x=>x.issue.id===issue().id&&x.request.id===requestId);if(found)workUI.collectionKey=found.key;route='collectioncenter';}else if(route==='report'){workUI.issueMode='chat';route='workbench';}else if(route==='source'){if(page==='logcenter'){workUI.logMode='source';route='logcenter';}else{workUI.issueMode='source';route='workbench';}}persistWork();originalGo(route);};
function openCapability(intent){if(intent==='parse'||intent==='read'||intent==='logSource')return setLogMode(intent==='logSource'?'source':intent);if(intent==='push'||intent==='retry')return setCollectionMode(intent);if(intent==='newCollect')return startAcquisitionFromWorkspace();setIssueMode({chat:'chat',issueSource:'source',evidence:'evidence',hypotheses:'hypotheses',handoff:'handoff'}[intent]||'chat');}
function openParsing(key){workUI.logKey=key;setLogMode('parse');}
function openSourceLogs(key){workUI.logStatus='';workUI.logQuery='';let x=fullLogSources().find(x=>x.key===key);if(!x?.request.task)return toast('索引尚未发布，请先查看解析结果');syncLog(x);setLogMode('read');}
function openSourceCollection(key){workUI.collectionStatus='';workUI.collectionQuery='';workUI.collectionKey=key;workUI.collectionMode='push';go('collectioncenter');}
function openLinkedInvestigation(key){let x=fullLogSources().find(x=>x.key===key);state.active=x.issue.id;taskId=x.request.task;setIssueMode('chat');}
function chooseIssueCapability(id,intent){state.active=id;taskId=null;requestId=null;closeModal();if(intent==='collect')return startAcquisitionFromWorkspace(id);setIssueMode({chat:'chat',issueSource:'source',evidence:'evidence',hypotheses:'hypotheses',handoff:'handoff'}[intent]||'chat');}
function filterRail(input,kind){workUI[kind+'Query']=input.value;let count=0;document.querySelectorAll('[data-rail-kind="'+kind+'"]').forEach(row=>{row.hidden=!row.dataset.railSearch.toLowerCase().includes(input.value.toLowerCase())||!!workUI[kind+'Status']&&row.dataset.railStatus!==workUI[kind+'Status'];if(!row.hidden)count++;});let empty=$('#rail-empty-'+kind);if(empty)empty.hidden=count>0;persistWork();}
function workspaceTabs(entries,active,handler){return `<div class="work-tabs" role="tablist">${entries.map(([value,text])=>`<button role="tab" aria-selected="${value===active}" class="${value===active?'tab-selected':''}" onclick="${handler}('${value}')">${text}</button>`).join('')}</div>`;}
function logRail(all,x){return `<div class="object-rail"><label for="rail-log">日志列表 · ${all.length}</label><input id="rail-log" placeholder="日志、设备、工单" value="${esc(workUI.logQuery)}" oninput="filterRail(this,'log')">${railStatusFilter('log',all.map(s=>sourceStatus(s.request)))}${all.map(s=>`<button class="rail-item ${s.key===x?.key?'chosen':''}" data-rail-kind="log" data-rail-status="${esc(sourceStatus(s.request))}" data-rail-search="${esc((s.request.task||s.request.id)+' '+s.request.device+' '+s.issue.id+' '+(s.asset?.version||s.issue.version)+' '+(s.asset?.build||s.issue.build)+' '+s.request.status+' '+(s.asset?.platform||'Native')+' '+s.request.files.map(f=>f.name).join(' '))}" onclick="setLogSelection('${s.key}')"><b>${s.request.task||s.request.id}</b>${badge(sourceStatus(s.request),s.request.task?'ok':'warn')}<small>${esc(s.request.device)} · ${esc(s.issue.id)}${s.asset?' · '+esc(s.asset.platform)+' · 本地文件':''}</small></button>`).join('')}<p class="muted" id="rail-empty-log" hidden>没有匹配日志。</p></div>`;}
function collectionRail(all,x){return `<div class="object-rail"><label for="rail-collection">回捞请求 · ${all.length}</label><input id="rail-collection" placeholder="请求、设备、工单" value="${esc(workUI.collectionQuery)}" oninput="filterRail(this,'collection')">${railStatusFilter('collection',all.map(s=>s.request.status))}${all.map(s=>`<button class="rail-item ${s.key===x?.key?'chosen':''}" data-rail-kind="collection" data-rail-status="${esc(s.request.status)}" data-rail-search="${esc(s.request.id+' '+s.request.device+' '+s.issue.id+' '+(s.asset?.version||s.issue.version)+' '+(s.asset?.build||s.issue.build)+' '+s.request.status+' '+(s.asset?.platform||'Native')+' '+s.request.files.map(f=>f.name).join(' '))}" onclick="setCollectionSelection('${s.key}')"><b>${s.request.id}</b>${badge(s.request.status,s.request.task?'ok':'warn')}<small>${esc(s.request.device)} · ${esc(s.issue.id)}${s.request.parent?' · 重试 '+s.request.parent:''}</small></button>`).join('')}<p class="muted" id="rail-empty-collection" hidden>没有匹配请求。</p></div>`;}
function issueRail(){return `<div class="object-rail"><label for="rail-issue">问题工单 · ${state.issues.length}</label><input id="rail-issue" placeholder="工单或问题" value="${esc(workUI.issueQuery)}" oninput="filterRail(this,'issue')">${state.issues.map(i=>`<button class="rail-item ${state.active===i.id?'chosen':''}" data-rail-kind="issue" data-rail-search="${esc(i.id+' '+i.title+' '+i.device)}" onclick="setIssueSelection('${i.id}')"><b>${esc(i.id)}</b>${badge(i.status)}<span>${esc(i.title)}</span><small>${i.investigation?.rounds.length||0} 轮对话 · ${i.investigation?.context.length??i.evidence.length} 项证据</small></button>`).join('')}<p class="muted" id="rail-empty-issue" hidden>没有匹配工单。</p></div>`;}
function objectHeader(title,description,actions=''){return `<div class="pane-header"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><div class="toolbar compact">${actions}</div></div>`;}
views.logcenter=function(){let all=receivedLogSources(),x=selectedLog();syncLog(x);let content=!x?'<div class="panel empty"><h3>尚未接收到日志文件</h3><p>先创建回捞请求并推进到文件上传。</p></div>':objectHeader(x.request.task||x.request.id,x.request.device+' · '+x.issue.id+' · '+sourceStatus(x.request),btn('下载正文',`downloadSourceSample('${x.key}')`,'',!x.request.task)+btn('进入工单排查',`openLinkedInvestigation('${x.key}')`))+workspaceTabs([['parse','文件与解析'],['read','搜索与上下文'],['source','源码与变更']],workUI.logMode,'setLogMode')+(workUI.logMode==='parse'?parseView(x):!x.request.task?'<div class="panel empty"><h3>日志尚不可查</h3><p>解析失败的文件不会展示为可搜索正文，请查看文件与解析记录。</p></div>':workUI.logMode==='read'?inlineLogReader():inlineSource());return heading('日志中心','选中日志后，直接阅读、搜索、查看解析结果或关联源码。')+`<div class="toolbar">${btn('上传日志文件','openLogImport()','primary')}${btn('载入 Web 样例','loadWebLogSample()')}${btn('下载 Web 样例','downloadWebLogSample()')}${btn('采集更多日志','startAcquisitionFromWorkspace()')}</div><div class="master-workspace">${logRail(all,x)}<div class="work-pane">${content}</div></div>`;};
function inlineLogReader(){return `<div class="panel"><div class="toolbar"><input aria-label="日志关键词" placeholder="关键词 / requestId" value="${esc(query)}" oninput="query=this.value;contextMode=false;renderLogs()"><select aria-label="日志级别" onchange="level=this.value;contextMode=false;renderLogs()">${['全部','ERROR','WARN','INFO','DEBUG','FATAL'].map(v=>`<option ${level===v?'selected':''}>${v}</option>`).join('')}</select>${btn('清除筛选',"query='';level='全部';contextMode=false;render()")}</div><small>${currentTask()?.assetId?'当前解析批次':'合成样例'}共 ${availableIndices().length} 条，筛选与上下文操作在此直接生效。</small></div><div class="inline-reader"><div class="panel"><div class="row"><h3>事件列表</h3><small id="count"></small></div><div id="context-banner"></div><div id="logs"></div></div><div class="panel" id="detail"></div></div>`;}
function inlineSource(){let t=currentTask();if(!t)return '<div class="panel empty">当前工单还没有可查日志，无法定位源码。</div>';let indices=availableIndices();if(!indices.includes(selected))selected=indices[0];let r=recordsForTask()[selected],matched=sourceMode==='matched'&&!!r.file&&r.sourceVerified!==false&&!!t.version&&!!t.build;return `<div class="panel"><div class="source-controls"><label>定位事件<select aria-label="源码定位事件" onchange="selected=Number(this.value);render()">${indices.map(n=>`<option value="${n}" ${selected===n?'selected':''}>L${n+1} · ${esc(recordsForTask()[n].module)}</option>`).join('')}</select></label><label>版本依据<select aria-label="源码匹配状态" onchange="sourceMode=this.value;render()"><option value="matched" ${sourceMode==='matched'?'selected':''}>演示：构建匹配</option><option value="candidate" ${sourceMode==='candidate'?'selected':''}>关键词候选</option><option value="missing" ${sourceMode==='missing'?'selected':''}>映射缺失</option></select></label></div><div class="evidence">${esc(t.id)} / L${selected+1} · ${esc(r.content)}</div>${sourceMode==='missing'?'<h3>缺少构建到提交的映射</h3><p>此时不能把其他版本的源码当作现场代码。</p>'+btn('记录缺失信息',"addGap('缺少构建与提交映射');toast('已记录源码映射缺失')")+btn('查看关键词候选',"sourceMode='candidate';render()"):`<div class="row"><h3>${esc(r.file||'NetworkMonitor.swift')}</h3>${badge(matched?'版本匹配（演示）':'未验证候选','warn')}</div><div class="code">${code(r)}</div><div class="toolbar">${btn('加入调查证据',r.file?'addSource()':"sourceMode='candidate';addSource()",'primary')}${btn('查看相关变更','changePreview()')}</div>`}<details><summary>定位依据与发布映射</summary><dl><dt>任务 / 事件</dt><dd>${esc(t.id)} / L${selected+1}</dd><dt>文件与行号</dt><dd>${r.file?esc(r.file+':'+r.line):'日志未记录文件行号，仅为模块候选'}</dd><dt>匹配方式</dt><dd>${matched?'合成埋点映射 · 模块、文件与行号':'尚无可验证的精确映射'}</dd><dt>构建依据</dt><dd>${t.version&&t.build?'采集/导入时保存的版本与构建':'旧任务未留存版本快照；当前工单版本仅作检索线索'}</dd><dt>发布 / 提交</dt><dd>${matched?'release/'+esc(t.version||issue().version)+' → demo-c81（虚构映射）':'未知，不能视为对应发布提交'}</dd></dl></details><div class="toolbar">${btn('返回对应日志',"go('logs')")}</div><small>来源 ${esc(t.version||issue().version)} / build ${esc(t.build||issue().build)} · 源码与提交均为合成示例。</small></div>`;}
views.collectioncenter=function(){let all=collectionSources(),eligible=workUI.collectionMode==='retry'?all.filter(x=>['部分成功','解析失败','上传失败','设备响应超时','推送失败','无可用日志','设备不支持'].includes(x.request.status)):all,x=selectedCollection();syncCollection(x);return heading('日志回捞','左侧选择请求，右侧直接追踪推送、上传和解析，或运行本地演示。')+`<div class="toolbar">${btn('回捞设备日志','startAcquisitionFromWorkspace()','primary')}${btn('上传日志文件','openLogImport()')}</div><p class="muted">回捞：取回设备或 Web 会话中已记录的日志。上传：导入手头已有文件并解析。调查中的证据缺口，可在问题工作台发起补充采集。</p>`+workspaceTabs([['push','推送与设备响应'],['files','文件与处理结果'],['retry','失败与重试']],workUI.collectionMode,'setCollectionMode')+`<div class="master-workspace">${collectionRail(eligible,x)}<div class="work-pane">${x?inlineCollection(x):'<div class="panel empty"><h3>暂无符合条件的请求</h3><p>可切换到推送视图或回捞设备日志。</p></div>'}</div></div>`;};
function inlineCollection(x){const r=x.request,terminal=M.terminal.includes(r.status),running=demoRuns.has(x.key),delivered=r.events.some(e=>e.text.includes('回执已收到')),confirmed=r.events.some(e=>e.text.includes('SDK 已确认'));let retryable=terminal&&!['完成','已取消'].includes(r.status);return objectHeader(r.id+' · '+r.device,x.issue.id+' · '+r.begin.replace('T',' ')+' — '+r.end.slice(11),badge(r.status,r.task?'ok':'warn'))+`<div class="panel"><div class="delivery-grid"><div><small>推送通道</small><b>${r.status==='推送失败'?'已拒绝':r.step>=1?'已接受':r.status==='已取消'?'未发送':'待发送'}</b></div><div><small>设备送达</small><b>${delivered?'已送达':r.status==='设备响应超时'?'未收到回执':'等待回执'}</b></div><div><small>SDK 确认</small><b>${confirmed?'已确认':'未确认'}</b></div><div><small>可查日志</small><b>${r.task||'尚未发布'}</b></div></div><div class="toolbar">${!terminal?`<label class="inline">演练结果<select aria-label="演练结果" ${r.step||running?'disabled':''} onchange="request().scenario=this.value;save()">${Object.entries({success:'全部成功',partial:'部分成功',timeout:'设备响应超时',pushfail:'推送失败',unsupported:'SDK 不支持',empty:'没有日志',uploadfail:'上传失败',parsefail:'解析失败'}).map(([v,label])=>`<option value="${v}" ${r.scenario===v?'selected':''}>${label}</option>`).join('')}</select></label>${btn(r.step?'推进下一步':'发送采集指令',`advanceInlineCollection('${x.key}')`,'',running)}${btn(running?'正在运行…':'运行到结果（演示）',`runInlineCollection('${x.key}')`,'primary',running)}${btn('取消请求',`cancelInlineCollection('${x.key}')`)}`:''}${retryable?btn('重试未完成部分',`retryInlineCollection('${x.key}')`,'primary'):''}${r.task?btn('打开返回日志',`openSourceLogs('${x.key}')`,'primary'):''}${btn('导出处理记录',`exportParseRecord('${x.key}')`)}</div><small>演示按钮仅推进本地回调。推送接受、设备送达与索引可查分别追踪。</small></div>${workUI.collectionMode==='files'||workUI.collectionMode==='retry'?`<div class="panel"><h3>文件与处理结果</h3>${r.files.length?`<table><thead><tr><th>文件</th><th>大小</th><th>状态</th></tr></thead><tbody>${r.files.map(f=>`<tr><td>${esc(f.name)}</td><td>${f.size}</td><td>${badge(f.status,f.status==='可查'?'ok':'warn')}</td></tr>`).join('')}</tbody></table>`:'<p>尚未收到文件。</p>'}${r.parent?`<p>此请求重试自 ${r.parent}，原有成功文件与记录保留。</p>`:''}${r.status==='部分成功'?'<div class="notice">成功文件可立即打开；重试仅包含未完成文件。</div>':''}</div>`:''}<div class="panel"><h3>回调与通知时间线</h3><label class="check"><input type="checkbox" ${r.notify?'checked':''} onchange="updateResultNotice('${x.key}',this.checked)">后续完成或失败时生成站内提醒</label><small>只影响后续本地结果提醒，已生成记录保留；与设备采集推送独立。</small><div class="timeline">${r.events.map(e=>`<p><small>${esc(e.time)}</small><br>${esc(e.text)}</p>`).join('')}</div><p class="muted">结果通知：${r.notify?'完成、部分成功或失败时记录本地提醒':'关闭'} · 有效期 ${r.ttl} 分钟 · 预算 ${r.budget} MiB</p></div>`;}
function advanceInlineCollection(key){let x=fullLogSources().find(x=>x.key===key);M.advance(x.request);persistWork();render();}
function runInlineCollection(key){if(demoRuns.has(key))return;const x=fullLogSources().find(x=>x.key===key);let timer=setInterval(()=>{M.advance(x.request);if(M.terminal.includes(x.request.status)){clearInterval(timer);demoRuns.delete(key);}save();if(page==='collectioncenter'&&workUI.collectionKey===key)render();},550);demoRuns.set(key,timer);render();}
function cancelInlineCollection(key){let timer=demoRuns.get(key);if(timer)clearInterval(timer);demoRuns.delete(key);let x=fullLogSources().find(x=>x.key===key);x.request.status='已取消';x.request.events.push({time:new Date().toLocaleTimeString('zh-CN'),text:'用户取消本地模拟请求，历史记录保留'});save();render();}
function retryInlineCollection(key){workUI.collectionStatus='';workUI.collectionQuery='';let x=fullLogSources().find(x=>x.key===key),result=M.retry(state,x.issue,x.request);if(!result)return toast('没有需要重试的文件');workUI.collectionMode='push';workUI.collectionKey=x.issue.id+'/'+result.request.id;save();render();}
function startAcquisitionFromWorkspace(id){const active=id||state.active,i=state.issues.find(i=>i.id===active)||state.issues[0];openModal('回捞设备日志',`<form onsubmit="submitInlineCollection(event)"><label for="new-capture-issue">关联工单</label><select id="new-capture-issue" onchange="fillCaptureIssue(this.value)">${state.issues.map(x=>`<option value="${x.id}" ${x.id===i.id?'selected':''}>${esc(x.id+' · '+x.title)}</option>`).join('')}</select><label for="new-capture-device">目标设备 *</label><input id="new-capture-device" required value="${esc(i.device)}"><div class="form-grid"><div><label for="new-capture-begin">日志开始时间</label><input type="datetime-local" id="new-capture-begin" required value="${i.begin}"></div><div><label for="new-capture-end">日志结束时间</label><input type="datetime-local" id="new-capture-end" required value="${i.end}"></div></div><label>日志种类</label><label class="check"><input name="capture-type" type="checkbox" value="应用日志" checked>应用日志</label><label class="check"><input name="capture-type" type="checkbox" value="网络日志" checked>网络日志</label><div class="form-grid"><div><label for="capture-budget">上传上限</label><select id="capture-budget"><option value="8">8 MiB</option><option value="32" selected>32 MiB</option><option value="64">64 MiB</option></select></div><div><label for="capture-ttl">请求有效期</label><select id="capture-ttl"><option value="15">15 分钟</option><option value="30" selected>30 分钟</option><option value="60">60 分钟</option></select></div></div><label class="check"><input id="capture-notify" type="checkbox" checked>完成或失败时生成站内提醒</label><p id="capture-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">创建回捞请求</button><button type="button" onclick="closeModal()">取消</button></div><small>仅创建本地模拟请求，不发送真实推送。</small></form>`,true);}
function fillCaptureIssue(id){let i=state.issues.find(i=>i.id===id);$('#new-capture-device').value=i.device;$('#new-capture-begin').value=i.begin;$('#new-capture-end').value=i.end;}
function submitInlineCollection(e){e.preventDefault();workUI.collectionStatus='';workUI.collectionQuery='';let i=state.issues.find(i=>i.id===$('#new-capture-issue').value),device=$('#new-capture-device').value.trim(),begin=$('#new-capture-begin').value,end=$('#new-capture-end').value,types=[...document.querySelectorAll('input[name="capture-type"]:checked')].map(x=>x.value);if(!device||begin>=end||!types.length){$('#capture-error').textContent='请填写设备，确保结束晚于开始，并选择至少一种日志。';return;}let result=M.create(state,i,{device,begin,end,types,budget:$('#capture-budget').value,ttl:$('#capture-ttl').value,notify:$('#capture-notify').checked});state.active=i.id;workUI.collectionKey=i.id+'/'+result.request.id;workUI.collectionMode='push';closeModal();persistWork();go('collectioncenter');}

views.workbench=()=>{let i=issue(),s=investigation(),mode=workUI.issueMode;return heading('问题排查工作台','围绕同一工单补充证据、追问、验证与保存结果')+`<div class="master-workspace">${issueRail()}<div class="work-pane">${objectHeader(i.id+' · '+i.title,i.device+' · '+i.status,btn('发起日志回捞',`startAcquisitionFromWorkspace('${i.id}')`))}${workspaceTabs([['chat','AI 对话'],['evidence','日志与源码证据'],['source','源码关联'],['hypotheses','假设验证'],['handoff','回写工单']],mode,'setIssueMode')}${`<div class="toolbar">${btn('粘贴日志 / 源码片段','pasteEvidence()')}${btn('导出对话与调查','exportConversation()','',!s.rounds.length)}</div>`}${mode==='chat'?currentRevisionNote(s)+`<div id="conversation">${conversationMarkup(s)||'<div class="panel empty">先描述问题，或补充日志与源码证据。</div>'}</div>`+composer():mode==='evidence'?evidencePanel():mode==='hypotheses'?verificationPlan()+hypothesesPanel():mode==='source'?`<div class="panel"><label>选择此工单的日志<select onchange="taskId=this.value;render()">${tasks().map(t=>`<option value="${t.id}" ${currentTask()?.id===t.id?'selected':''}>${t.id}</option>`).join('')}</select></label></div>`+inlineSource():inlineHandoff()}</div></div>`;};
function inlineHandoff(){let s=investigation(),i=issue();if(!lastAnswer(s))return '<div class="panel empty">先完成一次排查回答，再生成可编辑的工单结果。'+btn('开始提问',"setIssueMode('chat')",'primary')+'</div>';if(!draftHandoff)draftHandoff=i.handoffDraft?.snapshot||AI.handoff(s,lastAnswer(s).id);let h=draftHandoff,d=i.handoffDraft;return '<div class="panel">'+btn('根据最新回答重新生成草稿','regenerateHandoff()')+`<form oninput="persistHandoff()" onchange="persistHandoff()" onsubmit="saveChatTicket(event)"><div class="handoff-flow">对话 ${h.round} → ${h.evidence.length} 项证据 → ${h.verifications.length} 条验证 → 工单草稿</div>${h.revision!==h.answerRevision?'<div class="notice">本轮回答之后又增加了证据或验证。草稿同时保留旧回答与最新验证，请检查是否冲突；也可以先继续追问再回写。</div>':''}<div class="form-grid"><div><label for="chat-ticket-status">工单状态</label><select id="chat-ticket-status">${['调查中','待修复','待验证','已解决'].map(x=>`<option ${(d?.status||i.status)===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="chat-ticket-owner">负责人 *</label><input id="chat-ticket-owner" required value="${esc(d?.owner??(i.owner==='待分配'?'':i.owner))}" placeholder="填写处理负责人"></div></div><label for="chat-ticket-summary">可编辑的调查结果 *</label><textarea id="chat-ticket-summary" class="long" required>${esc(d?.summary??handoffText(h))}</textarea><details><summary>检查将附带的证据和验证记录</summary><div class="citation-list">${h.evidence.map(e=>`<span class="badge">${esc(e.label)} / ${esc(e.task)}</span>`).join('')}</div><p>${h.verifications.map(v=>esc(v.hypothesis+' · '+outcomes[v.outcome]+' · '+v.observation)).join('<br>')||'无人工验证记录'}</p></details><label class="check"><input id="chat-ticket-confirm" type="checkbox" ${d?.confirm?'checked':''}>我已核对事实、推断、验证记录与未知项</label><label class="check"><input id="chat-ticket-resolved" type="checkbox" ${d?.resolved?'checked':''}>本次问题已经完成复现与修复验证（模拟记录）</label><p id="chat-ticket-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">保存到本地工单</button><button type="button" onclick="setIssueMode('chat')">返回继续排查</button></div><small>只回写此浏览器的工单，不发送消息、不修改真实源码。</small></form>`+'</div>';}
analysisForm=function(){setIssueMode('chat');$('#chat-question')?.focus();};
showHypotheses=function(){setIssueMode('hypotheses');};
chatTicket=function(roundId){try{draftHandoff=issue().handoffDraft?.snapshot||AI.handoff(investigation(),roundId||lastAnswer(investigation())?.id);}catch(e){return toast(e.message);}workUI.issueMode='handoff';go('workbench');};
filterLogWorkspace=function(){};
const renderWorkspaceBase=render;
render=function(){renderWorkspaceBase();let section=primarySection(page);$('#nav').innerHTML=[['logcenter','日志中心',[['parse','文件与解析'],['read','搜索与阅读'],['source','关联源码']],'setLogMode'],['collectioncenter','日志回捞',[['push','推送与设备响应'],['files','返回文件'],['retry','失败与重试']],'setCollectionMode'],['issues','问题工单',[['chat','AI 对话'],['evidence','调查证据'],['hypotheses','假设验证'],['handoff','回写工单']],'setIssueMode']].map(([key,label,children,handler])=>`<button class="${section===key?'active':''}" onclick="${key==='issues'?"issueDetail=false;go('issues')":`go('${key}')`}">${label}</button>${section===key?`<div class="secondary-nav">${children.map(([mode,text])=>`<button onclick="${handler}('${mode}')">${text}</button>`).join('')}</div>`:''}`).join('');if(page==='logcenter'&&workUI.logMode==='read'&&selectedLog()?.request.task)renderLogs();for(let kind of ['log','collection','issue']){let input=$('#rail-'+kind);if(input&&(input.value||workUI[kind+'Status']))filterRail(input,kind);}if(page==='issues'){let top=document.createElement('div');top.className='toolbar';top.innerHTML=btn('进入排查工作台',"setIssueMode('chat')",'primary')+btn('发起日志回捞','startAcquisitionFromWorkspace()');$('#view').prepend(top);}persistWork();};
function persistHandoff(){if(!$('#chat-ticket-summary'))return;issue().handoffDraft={snapshot:draftHandoff,status:$('#chat-ticket-status').value,owner:$('#chat-ticket-owner').value,summary:$('#chat-ticket-summary').value,confirm:$('#chat-ticket-confirm').checked,resolved:$('#chat-ticket-resolved').checked};save();}
function regenerateHandoff(){delete issue().handoffDraft;draftHandoff=null;save();render();toast('已根据最新完成回答和验证记录重新生成');}
function railStatusFilter(kind,statuses){return `<label for="rail-${kind}-status">${kind==='log'?'日志状态':'回捞状态'}</label><select id="rail-${kind}-status" onchange="workUI['${kind}Status']=this.value;filterRail($('#rail-${kind}'),'${kind}')"><option value="">全部状态</option>${[...new Set([...statuses,...(workUI[kind+'Status']?[workUI[kind+'Status']]:[])])].map(v=>`<option ${workUI[kind+'Status']===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`;}
function verificationPlan(){let checks=issue().checks||[];return `<div class="panel"><h3>待验证计划</h3>${checks.length?checks.map((c,n)=>`<label class="check"><input type="checkbox" ${c.done?'checked':''} onchange="issue().checks[${n}].done=this.checked;save();render()">${esc(c.text)} · ${c.done?'已执行':'待执行'}</label>`).join(''):'<p class="muted">从源码相关变更加入的检查项会显示在这里。</p>'}${(issue().gaps||[]).map(g=>`<p class="notice">待补充：${esc(g)}</p>`).join('')}<small>勾选仅记录执行进度，假设结论仍需填写实际观察。</small></div>`;}
function updateResultNotice(key,value){let x=fullLogSources().find(x=>x.key===key);x.request.notify=value;save();render();toast(value?'已开启后续结果提醒':'已关闭后续结果提醒');}
function openIssueCollection(){workUI.collectionStatus='';workUI.collectionQuery='';let r=issue().requests.at(-1);if(!r)return collectForm();workUI.collectionMode='push';workUI.collectionKey=issue().id+'/'+r.id;requestId=r.id;go('collectioncenter');}
function openIssueLogs(){let t=tasks().at(-1);if(!t){toast('此工单尚无可查日志，请先完成采集与解析');return;}taskId=t.id;go('logs');}
flow=function(){return `<div class="journey">${btn('工单详情',"issueDetail=true;go('issues')")}${btn('回捞与推送','openIssueCollection()')}${btn('日志与源码','openIssueLogs()')}${btn('AI 调查',"setIssueMode('chat')")}${btn('工单更新',"setIssueMode('handoff')")}</div>`;};
issueDetail=!!workUI.issueDetail;
let initialRoute=location.hash.slice(1)||'issues';
if(['report','logs','collect','parsing','source'].includes(initialRoute))go(initialRoute);else{page=names[initialRoute]?initialRoute:'issues';render();}
